from inventory import add_item, remove_item, total_value


def test_add_accumulates():
    inv = {}
    add_item(inv, "apple", 3)
    add_item(inv, "apple", 2)
    assert inv["apple"] == 5, inv
    print("add accumulates: OK")


def test_add_negative_raises():
    inv = {}
    try:
        add_item(inv, "apple", -1)
    except ValueError:
        print("add negative raises ValueError: OK")
    else:
        raise AssertionError("expected ValueError")


def test_remove_unknown_raises():
    inv = {"apple": 3}
    try:
        remove_item(inv, "banana", 1)
    except KeyError:
        print("remove unknown raises KeyError: OK")
    else:
        raise AssertionError("expected KeyError")


